)

// serveCmd represents the serve command
var serveCmd = &cobra.Command{
	Use:   "serve",
	Short: "Start the badge-api server.",
	Long:  `Start the badge-api server. This will start the badge-api server on the port specified in the configuration file or provided as a flag. Defaults to :8080`,
	RunE: func(cmd *cobra.Command, args []string) error {
		return api.Start(cmd.Flag("port").Value.String())
	},
}

func init() {
	rootCmd.AddCommand(serveCmd)

	// Here you will define your flags and configuration settings.

	// Cobra supports Persistent Flags which will work for this command
	// and all subcommands, e.g.:
	serveCmd.PersistentFlags().StringP("port", "p", "8080", "Port to start the server on")

	// Cobra supports local flags which will only run when this command
	// is called directly, e.g.:
	// serveCmd.Flags().BoolP("toggle", "t", false, "Help message for toggle")
}
